import { useEffect, useState } from "react";
import axios from "axios";

import {
  fetchLoggedUser,
  fetchUserRepos,
  fetchCommits,
  uploadFile,
  fetchPRHeatmap,
  fetchMergeHeatmap,
} from "./api/githubApi";

import { fetchTimeline } from "./api/jiraApi";
import MonthYearPicker from "./components/MonthYearPicker";

import "./App.css";

function App() {
  // STATE
  const [owner, setOwner] = useState("");
  const [repos, setRepos] = useState([]);
  const [selectedRepo, setSelectedRepo] = useState("");

  const [jiraKey, setJiraKey] = useState("");
  const [timeline, setTimeline] = useState(null);
  const [pipeline, setPipeline] = useState(null);
  const [loadingTimeline, setLoadingTimeline] = useState(false);

  const [commitHeatmap, setCommitHeatmap] = useState({});
  const [prHeatmap, setPrHeatmap] = useState({});
  const [mergeHeatmap, setMergeHeatmap] = useState({});
  const [commitList, setCommitList] = useState([]);

  const [selectedFile, setSelectedFile] = useState(null);
  const [uploadMessage, setUploadMessage] = useState("Upload via dashboard");

  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [userCreatedAt, setUserCreatedAt] = useState("");

  const [actionType, setActionType] = useState("commits");
  const [darkMode, setDarkMode] = useState(true);

  // DARK / LIGHT MODE
  useEffect(() => {
    document.body.style.backgroundColor = darkMode ? "#020617" : "#F8FAFC";
    document.body.style.color = darkMode ? "#E5E7EB" : "#020617";
  }, [darkMode]);

  // HANDLE LOGIN TOKEN
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const token = params.get("token");
    if (token) {
      localStorage.setItem("token", token);
      window.history.replaceState({}, document.title, window.location.pathname);
    }
  }, []);

  // LOAD USER + REPOS
  useEffect(() => {
    const token = localStorage.getItem("token");
    if (token) {
      fetchLoggedUser().then((res) => {
        setOwner(res.data.login);
        setUserCreatedAt(res.data.created_at);
      });
      fetchUserRepos().then((res) => setRepos(res.data));
    }
  }, []);

  // TIMELINE LOADER
  const loadTimeline = async () => {
    setLoadingTimeline(true);
    try {
      const response = await fetchTimeline({ key: jiraKey });
      setTimeline(response.data);
    } catch (error) {
      console.error("Timeline error:", error);
      alert("Failed to load timeline");
    }
    setLoadingTimeline(false);
  };

  // PIPELINE LOADER
  const loadPipeline = async () => {
    setLoadingTimeline(true);
    try {
      const response = await fetchTimeline({ key: jiraKey });
      setPipeline(response.data);
    } catch (error) {
      console.error("Pipeline error:", error);
      alert("Failed to load pipeline");
    }
    setLoadingTimeline(false);
  };

  // HEATMAP: COMMITS
  const buildCommitHeatmap = async (payload) => {
    try {
      const res = await fetchCommits(payload);
      setCommitHeatmap(res.data);
      setCommitList(res.data);
    } catch (error) {
      console.error("Commit heatmap error:", error);
    }
  };

  // HEATMAP: PRS
  const buildPRHeatmap = async (payload) => {
    try {
      const res = await fetchPRHeatmap(payload);
      setPrHeatmap(res.data);
    } catch (error) {
      console.error("PR heatmap error:", error);
    }
  };

  // HEATMAP: MERGED PRS
  const buildMergeHeatmap = async (payload) => {
    try {
      const res = await fetchMergeHeatmap(payload);
      setMergeHeatmap(res.data);
    } catch (error) {
      console.error("Merge heatmap error:", error);
    }
  };

  // ANALYZE BUTTON
  const fetchData = async () => {
    if (!selectedRepo) {
      alert("Please select a repo");
      return;
    }

    const payload = {
      owner: owner,
      repo: selectedRepo,
      startDate: startDate,
      endDate: endDate,
    };

    if (actionType === "commits") {
      await buildCommitHeatmap(payload);
    } else if (actionType === "prs") {
      await buildPRHeatmap(payload);
    } else if (actionType === "merges") {
      await buildMergeHeatmap(payload);
    }
  };

  // UPLOAD FILE
  const handleUpload = async () => {
    if (!selectedFile || !selectedRepo) {
      alert("Please select a file and repo");
      return;
    }

    const formData = new FormData();
    formData.append("owner", owner);
    formData.append("repo", selectedRepo);
    formData.append("path", "README.md");
    formData.append("content", await selectedFile.text());
    formData.append("message", `Update from dashboard`);

    try {
      await uploadFile(formData);
      setUploadMessage("✅ Upload successful!");
      setTimeout(() => setUploadMessage("Upload via dashboard"), 3000);
    } catch (error) {
      setUploadMessage("❌ Upload failed");
    }
  };

  // HEATMAP RENDER
  const renderHeatmap = () => {
    if (actionType === "commits" && Object.keys(commitHeatmap).length === 0)
      return null;
    if (actionType === "prs" && Object.keys(prHeatmap).length === 0) return null;
    if (actionType === "merges" && Object.keys(mergeHeatmap).length === 0)
      return null;

    const data =
      actionType === "commits"
        ? commitHeatmap
        : actionType === "prs"
        ? prHeatmap
        : mergeHeatmap;

    return (
      <div className="heatmap-container">
        <h3>
          {actionType === "commits"
            ? "Commit Activity"
            : actionType === "prs"
            ? "PR Activity"
            : "Merge Activity"}
        </h3>
        <div className="heatmap-grid">
          {Object.entries(data).map(([date, count]) => {
            const level = Math.min(count, 4);
            return (
              <div key={date} className={`heat-box level-${level}`}>
                <span className="tooltip">
                  {date}: {count}
                </span>
              </div>
            );
          })}
        </div>
      </div>
    );
  };

  // UI
  if (!localStorage.getItem("token")) {
    return (
      <div className="container" style={{ textAlign: "center", padding: "50px" }}>
        <h1>GitHub Tracker</h1>
        <p>Click below to login with GitHub</p>
        <a href="http://localhost:8080/auth/github" className="button primary">
          Login with GitHub
        </a>
      </div>
    );
  }

  return (
    <div className="container">
      <div className="topbar">
        <h1>📊 GitHub Analytics</h1>
        <button onClick={() => setDarkMode(!darkMode)}>
          {darkMode ? "☀️ Light" : "🌙 Dark"}
        </button>
      </div>

      {owner && <p>Welcome, <strong>{owner}</strong>!</p>}

      <div className="form-area">
        <div>
          <label>Select Repository:</label>
          <select
            value={selectedRepo}
            onChange={(e) => setSelectedRepo(e.target.value)}
          >
            <option value="">-- Choose a repo --</option>
            {repos.map((repo) => (
              <option key={repo.id} value={repo.name}>
                {repo.name}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label>Action:</label>
          <select value={actionType} onChange={(e) => setActionType(e.target.value)}>
            <option value="commits">Commit Heatmap</option>
            <option value="prs">PR Heatmap</option>
            <option value="merges">Merge Heatmap</option>
          </select>
        </div>

        <MonthYearPicker
          startDate={startDate}
          setStartDate={setStartDate}
          endDate={endDate}
          setEndDate={setEndDate}
        />

        <button className="primary" onClick={fetchData}>
          Analyze
        </button>
      </div>

      {renderHeatmap()}

      <div className="form-area">
        <h3>Upload File</h3>
        <input
          type="file"
          onChange={(e) => setSelectedFile(e.target.files?.[0] || null)}
        />
        <button className="primary" onClick={handleUpload}>
          {uploadMessage}
        </button>
      </div>

      {timeline && (
        <div className="timeline-box">
          <h3>Timeline</h3>
          {timeline.timeline?.map((event, idx) => (
            <div key={idx} className="timeline-event">
              <strong>{event.type}</strong>: {event.message} by {event.actor}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default App;
